<?php
namespace S2NRI;

defined( 'ABSPATH' ) || exit;

/**
 * Installer — activation, migrations, seeding. Fully idempotent.
 *
 * TRACE: Called on activation hook and on plugins_loaded when version mismatch.
 *        Creates all 18 custom tables, seeds 20 service categories, seeds platform settings.
 *        Preconditions: $wpdb available, WordPress loaded.
 *        Postconditions: All tables exist, reference data populated, cron jobs scheduled.
 *        Edge cases: Re-run safe — all CREATE TABLE uses IF NOT EXISTS, inserts check before inserting.
 */
class Installer {

    // ── Activation ────────────────────────────────────────────────────────────

    public static function activate(): void {
        global $wpdb;
        if ( function_exists( 'opcache_reset' ) ) opcache_reset();
        try {
            self::runMigrations();
            self::seedData();
            self::importAllFormFields(); // Issue 12 FIX: ensure Dropdown Data Manager is populated
            self::scheduleJobs();
            self::writePwaFiles();
            update_option( 's2nri_db_version', S2NRI_VERSION );
            update_option( 's2nri_activated_at', current_time( 'mysql' ) );
        } catch ( \Throwable $e ) {
            error_log( '[S2NRI Activation] ' . $e->getMessage() . ' in ' . $e->getFile() . ':' . $e->getLine() );
        }
        // Register ALL rewrite rules before flushing so /s2nri-admin/, /portal/,
        // /s2nri-builder/ and /api/v1/* are all present in the saved rewrite table
        // from the very first activation — without this users see 404 on all portal paths.
        \S2NRI\Bootstrap::registerRewrites();
        \S2NRI\Portal::ensureRewriteRules();
        \S2NRI\BuilderPage::registerRewriteRules();
        flush_rewrite_rules( true );
        \S2NRI\Bootstrap::ensureHtaccess();
        \S2NRI\Portal::ensureHtaccess();
        if ( ob_get_level() > 0 ) ob_end_clean();
    }

    // ── Deactivation ──────────────────────────────────────────────────────────

    public static function deactivate(): void {
        $hooks = [ 's2nri_job_notifications', 's2nri_job_quote_reminders', 's2nri_job_sitemap', 's2nri_job_cleanup' ];
        foreach ( $hooks as $hook ) { wp_clear_scheduled_hook( $hook ); }
        flush_rewrite_rules();
    }

    // ── Migrations ────────────────────────────────────────────────────────────

    public static function runMigrations(): void {
        global $wpdb;
        $c = $wpdb->get_charset_collate();
        $p = $wpdb->prefix;

        // ── Platform Settings ─────────────────────────────────────────────────
        $wpdb->query( "CREATE TABLE IF NOT EXISTS `{$p}s2nri_settings` (
            `id`            INT UNSIGNED     NOT NULL AUTO_INCREMENT,
            `setting_key`   VARCHAR(100)     NOT NULL,
            `setting_value` LONGTEXT         NOT NULL DEFAULT '',
            `is_public`     TINYINT(1)       NOT NULL DEFAULT 0,
            `updated_at`    DATETIME         NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
            PRIMARY KEY (`id`),
            UNIQUE KEY `uq_key` (`setting_key`)
        ) $c" );

        // ── Contact Form Messages ────────────────────────────────────────────
        // ADDED: previously the public contact form had NO database record
        // at all — the message existed only as a fire-and-forget wp_mail()
        // call whose return value was never even checked. Any mail-server
        // hiccup (extremely common on shared hosting — SMTP misconfig,
        // spam filters) permanently lost the customer's message with zero
        // trace anywhere. This table gives it real durability: the
        // message is saved BEFORE attempting to email it, so even a
        // failed send leaves a recoverable record an admin can review.
        $wpdb->query( "CREATE TABLE IF NOT EXISTS `{$p}s2nri_contact_messages` (
            `id`           INT UNSIGNED     NOT NULL AUTO_INCREMENT,
            `name`         VARCHAR(150)     NOT NULL,
            `email`        VARCHAR(200)     NOT NULL,
            `phone`        VARCHAR(20)      NOT NULL DEFAULT '',
            `subject`      VARCHAR(255)     NOT NULL DEFAULT '',
            `message`      TEXT             NOT NULL,
            `email_sent`   TINYINT(1)       NOT NULL DEFAULT 0,
            `is_read`      TINYINT(1)       NOT NULL DEFAULT 0,
            `created_at`   DATETIME         NOT NULL DEFAULT CURRENT_TIMESTAMP,
            PRIMARY KEY (`id`),
            KEY `idx_created` (`created_at`),
            KEY `idx_unread` (`is_read`)
        ) $c" );

        // ── Service Categories ────────────────────────────────────────────────
        $wpdb->query( "CREATE TABLE IF NOT EXISTS `{$p}s2nri_categories` (
            `id`            INT UNSIGNED     NOT NULL AUTO_INCREMENT,
            `slug`          VARCHAR(100)     NOT NULL,
            `name`          VARCHAR(150)     NOT NULL,
            `name_hi`       VARCHAR(150)     NOT NULL DEFAULT '',
            `description`   TEXT,
            `icon`          VARCHAR(100)     NOT NULL DEFAULT '📋',
            `color`         VARCHAR(20)      NOT NULL DEFAULT '#4A6FA5',
            `sort_order`    SMALLINT UNSIGNED NOT NULL DEFAULT 0,
            `image_url`     VARCHAR(500)     NOT NULL DEFAULT '',
            `is_active`     TINYINT(1)       NOT NULL DEFAULT 1,
            `seo_title`     VARCHAR(200),
            `seo_desc`      VARCHAR(400),
            `created_at`    DATETIME         NOT NULL DEFAULT CURRENT_TIMESTAMP,
            PRIMARY KEY (`id`),
            UNIQUE KEY `uq_slug` (`slug`),
            KEY `idx_active_sort` (`is_active`, `sort_order`)
        ) $c" );

        // ── Services ──────────────────────────────────────────────────────────
        $wpdb->query( "CREATE TABLE IF NOT EXISTS `{$p}s2nri_services` (
            `id`              INT UNSIGNED     NOT NULL AUTO_INCREMENT,
            `category_id`     INT UNSIGNED     NOT NULL,
            `slug`            VARCHAR(150)     NOT NULL,
            `name`            VARCHAR(200)     NOT NULL,
            `name_hi`         VARCHAR(200)     NOT NULL DEFAULT '',
            `icon`            VARCHAR(100)     NOT NULL DEFAULT '📋' COMMENT 'Emoji or icon code shown in admin list',
            `short_desc`      VARCHAR(400),
            `description`     LONGTEXT,
            `pricing_model`   ENUM('quote','fixed','range') NOT NULL DEFAULT 'quote',
            `base_price`      DECIMAL(10,2)    DEFAULT NULL,
            `price_min`       DECIMAL(10,2)    DEFAULT NULL,
            `price_max`       DECIMAL(10,2)    DEFAULT NULL,
            `turnaround_days` SMALLINT UNSIGNED NOT NULL DEFAULT 7,
            `form_schema`     JSON             COMMENT 'Dynamic form fields JSON',
            `required_docs`   JSON             COMMENT 'List of required documents',
            `image_url`       VARCHAR(500)     NOT NULL DEFAULT '',
            `is_active`       TINYINT(1)       NOT NULL DEFAULT 1,
            `sort_order`      SMALLINT UNSIGNED NOT NULL DEFAULT 0,
            `seo_title`       VARCHAR(200),
            `seo_desc`        VARCHAR(400),
            `created_at`      DATETIME         NOT NULL DEFAULT CURRENT_TIMESTAMP,
            `updated_at`      DATETIME         NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
            PRIMARY KEY (`id`),
            UNIQUE KEY `uq_slug` (`slug`),
            KEY `idx_cat_active` (`category_id`, `is_active`, `sort_order`)
