        // ── Bookings ──────────────────────────────────────────────────────────
        $wpdb->query( "CREATE TABLE IF NOT EXISTS `{$p}s2nri_bookings` (
            `id`                INT UNSIGNED     NOT NULL AUTO_INCREMENT,
            `booking_ref`       VARCHAR(20)      NOT NULL COMMENT 'Human-readable ref e.g. S2N-2024-001',
            `customer_id`       INT UNSIGNED     NOT NULL,
            `service_id`        INT UNSIGNED     NOT NULL,
            `category_id`       INT UNSIGNED     NOT NULL,
            `assigned_to`       BIGINT UNSIGNED  DEFAULT NULL COMMENT 'WP staff user ID',
            `status`            ENUM('submitted','under_review','quote_sent','quote_approved','in_progress','docs_requested','docs_received','processing','completed','cancelled','on_hold') NOT NULL DEFAULT 'submitted',
