            `field_data`        LONGTEXT         NOT NULL DEFAULT '{}' COMMENT 'JSON of submitted form fields',
            `notes`             TEXT             COMMENT 'Internal staff notes',
            `customer_notes`    TEXT             COMMENT 'Notes visible to customer',
            `payment_status`    ENUM('pending','bank_transfer_pending','paid','refunded','waived') NOT NULL DEFAULT 'pending',
            `payment_method`    ENUM('bank_transfer','razorpay','stripe','paypal','waived') DEFAULT NULL,
