            $wpdb->query( "ALTER TABLE `{$p}s2nri_bookings` ADD COLUMN `delivery_note` VARCHAR(200) DEFAULT NULL AFTER `delivery_working_days`" );
        }
        if ( $bk_cols && ! in_array( 'vendor_id', $bk_cols, true ) ) {
            $wpdb->query( "ALTER TABLE `{$p}s2nri_bookings` ADD COLUMN `vendor_id` INT UNSIGNED DEFAULT NULL COMMENT 'FK to s2nri_vendors' AFTER `assigned_to`" );
            $wpdb->query( "ALTER TABLE `{$p}s2nri_bookings` ADD INDEX `idx_vendor` (`vendor_id`)" );
        }
        if ( $bk_cols && ! in_array( 'shipping_type', $bk_cols, true ) ) {
            $wpdb->query( "ALTER TABLE `{$p}s2nri_bookings` ADD COLUMN `shipping_type` ENUM('domestic','international','none') NOT NULL DEFAULT 'domestic' AFTER `payment_method`" );
        }

        // ── Phase 1 ALTER: nri_ref sequential counter ──────────────────────────
        // s2nri_ref_counter: used for atomic NRI-YYYY-NNNN sequence (M-30)
        $wpdb->query( "CREATE TABLE IF NOT EXISTS `{$p}s2nri_ref_counter` (
            `year`        SMALLINT UNSIGNED NOT NULL,
            `last_seq`    INT UNSIGNED      NOT NULL DEFAULT 0,
            PRIMARY KEY (`year`)
        ) $c;" );

        // s2nri_staff: add phone column (was referenced in queries but missing from schema)
        $staff_cols = array_column( $wpdb->get_results( "SHOW COLUMNS FROM `{$p}s2nri_staff`", ARRAY_A ) ?: [], 'Field' );
        if ( $staff_cols && ! in_array( 'phone', $staff_cols, true ) ) {
            $wpdb->query( "ALTER TABLE `{$p}s2nri_staff` ADD COLUMN `phone` VARCHAR(20) DEFAULT NULL AFTER `s2nri_role`" );
        }

        error_log( '[S2NRI] Migrations complete.' );
    }

