    /**
     * Issue 12 FIX: Bulk-import qualification_schema into s2nri_form_fields for all services.
     * Called on activation and migration so Dropdown Data Manager is never empty.
     * Idempotent — skips services that already have fields in the table.
     */
    public static function importAllFormFields(): void {
        global $wpdb;
        $p = $wpdb->prefix;

        $services = $wpdb->get_results(
            "SELECT id, qualification_schema, form_schema
             FROM `{$p}s2nri_services`
             WHERE is_active = 1
               AND (qualification_schema IS NOT NULL OR form_schema IS NOT NULL)",
            ARRAY_A
        ) ?: [];

        $type_map = [ 'multi' => 'checkbox', 'toggle' => 'checkbox', 'paragraph' => 'textarea' ];
        $allowed  = ['text','number','email','phone','textarea','select',
                     'dropdown','searchable','radio','checkbox','date','file'];

        foreach ( $services as $svc ) {
            $sid = (int) $svc['id'];

            // Skip if already imported
            $count = (int) $wpdb->get_var( $wpdb->prepare(
                "SELECT COUNT(*) FROM `{$p}s2nri_form_fields` WHERE service_id = %d", $sid
            ) );
            if ( $count > 0 ) continue;

            // Pick the schema
            $schema = null;
            foreach ( ['qualification_schema', 'form_schema'] as $col ) {
                if ( ! empty( $svc[ $col ] ) ) {
                    $dec = json_decode( $svc[ $col ], true );
                    if ( is_array( $dec ) && $dec ) { $schema = $dec; break; }
                }
            }
            if ( ! $schema ) continue;

            $sort = 1;
            foreach ( $schema as $f ) {
                $key  = sanitize_key( $f['key'] ?? '' );
                $type = sanitize_key( $f['type'] ?? 'text' );
                if ( ! $key ) continue;
                if ( isset( $type_map[ $type ] ) ) $type = $type_map[ $type ];
                if ( ! in_array( $type, $allowed, true ) ) $type = 'text';

                $opts = ( is_array( $f['options'] ?? null ) && $f['options'] )
                    ? wp_json_encode( array_values( $f['options'] ) ) : null;
                $cond = ! empty( $f['conditions'] ) ? wp_json_encode( $f['conditions'] ) : null;

                $wpdb->insert( $p . 's2nri_form_fields', [
                    'service_id'  => $sid,
                    'field_key'   => $key,
                    'label'       => sanitize_text_field( $f['label'] ?? $key ),
                    'field_type'  => $type,
                    'step'        => (int) ( $f['step'] ?? 1 ),
                    'required'    => ! empty( $f['required'] ) ? 1 : 0,
                    'placeholder' => sanitize_text_field( $f['placeholder'] ?? '' ),
                    'help_text'   => sanitize_textarea_field( $f['description'] ?? $f['help_text'] ?? '' ),
                    'options'     => $opts,
                    'conditions'  => $cond,
                    'is_active'   => 1,
                    'sort_order'  => $sort++,
                ] );
            }
        }
    }

    private static function scheduleJobs(): void {
        if ( ! wp_next_scheduled( 's2nri_job_notifications' ) ) {
            wp_schedule_event( time(), 'hourly', 's2nri_job_notifications' );
        }
        if ( ! wp_next_scheduled( 's2nri_job_quote_reminders' ) ) {
            wp_schedule_event( time(), 'twicedaily', 's2nri_job_quote_reminders' );
        }
        if ( ! wp_next_scheduled( 's2nri_job_cleanup' ) ) {
            wp_schedule_event( time(), 'daily', 's2nri_job_cleanup' );
        }
        if ( ! wp_next_scheduled( 's2nri_job_sitemap' ) ) {
            wp_schedule_event( time(), 'daily', 's2nri_job_sitemap' );
        }
    }

    // ── PWA files ─────────────────────────────────────────────────────────────

    private static function writePwaFiles(): void {
        // Single source of truth: assets/sw.js (also served dynamically by
        // PWA::serveServiceWorker() as a fallback route). Previously this
        // function carried its own separate, older, drifted copy of the
        // service worker script — the two could silently diverge, and worse,
        // this static write is the one that actually reaches browsers
        // (static files on disk are served directly, before WordPress's own
        // /sw.js route ever runs), so a stale copy here could never be fixed
        // by changing the PHP-served version alone.
        $sw_source = S2NRI_DIR . 'assets/sw.js';
        $sw = file_exists( $sw_source ) ? file_get_contents( $sw_source ) : false;

        if ( $sw !== false ) {
            $written = @file_put_contents( ABSPATH . 'sw.js', $sw );
            // BUG THIS FIXES: the previous version of this line used the same
            // @file_put_contents() call but never checked the return value.
            // On hosts where the web root isn't writable (confirmed on this
            // exact site — see wp-content/debug.log entries for .htaccess:
            // "Failed to open stream: Permission denied"), this call fails
            // the same way, silently. sw.js then never gets created, /sw.js
            // requests fall through to WordPress's dynamic PHP route instead
            // of the intended static file, and the site keeps running
            // whatever the PHP fallback serves — invisibly, with the
            // installer reporting success regardless.
            if ( $written === false ) {
                error_log( 'S2NRI Installer: failed to write ' . ABSPATH . 'sw.js — web root is not writable by PHP. The dynamic /sw.js PHP route (PWA::serveServiceWorker) will serve visitors instead; confirm assets/sw.js is present and up to date.' );
            }
        } else {
            error_log( 'S2NRI Installer: assets/sw.js not found in plugin package — service worker was not written to the site root.' );
        }

        // Write manifest.json with static asset icon URLs.
        // Static files are served directly by the web server — no WordPress boot,
        // no CDN interference, no dynamic endpoint failures.
        // The icon-192.png and icon-512.png files live in the plugin's assets/ directory.
        $site_name  = get_option( 'blogname', 'Services2NRI' );
        $icon_192   = plugins_url( 'assets/icon-192.png', S2NRI_FILE );
        $icon_512   = plugins_url( 'assets/icon-512.png', S2NRI_FILE );
        $manifest   = wp_json_encode( [
            'name'             => $site_name,
            'short_name'       => 'S2NRI',
            'start_url'        => '/',
            'display'          => 'standalone',
            'background_color' => '#ffffff',
            'theme_color'      => '#4A6FA5',
            'description'      => 'NRI Services — Property Management, Documentation, OCI, Passports and more',
            'icons'            => [
                [ 'src' => $icon_192, 'sizes' => '192x192', 'type' => 'image/png' ],
                [ 'src' => $icon_512, 'sizes' => '512x512', 'type' => 'image/png' ],
            ],
        ], JSON_UNESCAPED_SLASHES | JSON_PRETTY_PRINT );
        @file_put_contents( ABSPATH . 'manifest.json', $manifest );
    }

