            'epf-pf-withdrawal' => '[{"key":"uan_status","label":"Current status of your UAN (Universal Account Number)","type":"radio","required":true,"step":1,"score_weight":25,"options":["UAN is active and I can log in to EPFO portal","UAN exists but not activated on portal","I have a PF number but don\'t know my UAN","I don\'t know my PF number or UAN at all","I have multiple UAN numbers (changed jobs without linking)"],"eligibility_rule":{"warn_if":"UAN exists but not activated on portal","message":"An inactive UAN adds 2–3 weeks. Activation is the first priority and we will handle it.","severity":"soft"}},{"key":"kyc_seeding","label":"KYC documents linked to your UAN","type":"radio","required":true,"step":1,"score_weight":20,"options":["All three linked — Aadhaar + PAN + Bank Account","Partially linked — Aadhaar linked but not PAN / bank","Only Aadhaar linked","Nothing is linked","Not sure — need to check"],"eligibility_rule":{"warn_if":"Nothing is linked","message":"KYC seeding of all three is mandatory before withdrawal. This is the most common reason for PF withdrawal rejection.","severity":"soft"}},{"key":"withdrawal_type","label":"Type of withdrawal you are requesting","type":"select","required":true,"step":1,"score_weight":15,"options":["Full PF + Pension (EPS) — resigned and not employed anywhere","Full PF withdrawal only — NOT EPS / pension part","Partial Advance — Housing (home loan / purchase)","Partial Advance — Medical (self or family hospitalisation)","Partial Advance — Marriage (self / sibling / children)","Partial Advance — Education (children\'s higher education)","Pension (EPS) only — PF already withdrawn separately","Not sure — advise me"]},{"key":"employer_count","label":"How many different employers have you contributed PF with?","type":"number","required":true,"step":2,"score_weight":5,"description":"Multiple employers without UAN linking creates separate accounts that must be merged","placeholder":"e.g. 3"},{"key":"transfer_needed","label":"Do you need to transfer PF from old employer to current UAN first?","type":"radio","required":true,"step":2,"score_weight":10,"options":["No — all accounts already merged into one UAN","Yes — old PF accounts need to be transferred / merged first","Not sure — need to check","Have only one employer — no transfer needed"]},{"key":"employer_name","label":"Last Employer\'s Name","type":"text","required":true,"step":2,"score_weight":5,"placeholder":"e.g. Infosys Limited"},{"key":"date_leaving","label":"Date of Leaving Last Employment","type":"date","required":true,"step":2,"score_weight":5,"description":"PF can be withdrawn after 2 months of resignation if not re-employed"},{"key":"currently_employed","label":"Are you currently employed anywhere?","type":"radio","required":true,"step":2,"score_weight":10,"options":["No — I am NOT working anywhere","Yes — employed in India (only partial withdrawal allowed)","Yes — employed abroad (NRI)"],"eligibility_rule":{"warn_if":"Yes — employed in India (only partial withdrawal allowed)","message":"Full PF withdrawal is not allowed while employed in India. Only partial advances are permitted.","severity":"soft"}},{"key":"uan_number","label":"Your UAN Number","type":"text","required":false,"step":3,"score_weight":10,"conditions":{"show_if":{"uan_status":"UAN is active and I can log in to EPFO portal"}},"placeholder":"12-digit UAN"},{"key":"bank_account","label":"Indian Bank Account Number (for PF credit)","type":"text","required":true,"step":3,"score_weight":10},{"key":"ifsc","label":"IFSC Code","type":"text","required":true,"step":3,"score_weight":10,"placeholder":"e.g. HDFC0001234"},{"key":"aadhaar_linked","label":"Is your Aadhaar linked with your UAN / EPFO account?","type":"radio","required":true,"step":3,"score_weight":10,"options":["Yes — Aadhaar seeded and verified","Yes — seeded but not verified","No — not linked","Not sure"],"description":"Aadhaar linking is mandatory for online PF withdrawal since 2021"},{"key":"docs_avail