            'power-of-attorney' => '[{"key":"poa_purpose","label":"What will this POA be used for? (PRIMARY purpose)","type":"select","required":true,"step":1,"score_weight":20,"options":["Property Sale — selling Indian property on my behalf","Property Purchase — buying property on my behalf","Property Management — rent, repairs, maintenance","Bank Account Operations — access and manage Indian bank accounts","Legal Proceedings — court cases, disputes","Loan / Mortgage Application or Closure","Vehicle Sale or Transfer","Inheritance / Estate Settlement","Company / Business Affairs","Government / Tax Matters","Multiple purposes — General POA","Other"]},{"key":"poa_type","label":"Type of POA required","type":"radio","required":true,"step":1,"score_weight":15,"options":["Specific / Limited POA — for ONE transaction only","General POA — broad authority over multiple matters","Irrevocable POA — cannot be cancelled once executed","Not sure — please advise"],"description":"Specific POA is safer for property transactions. General POA is more flexible but riskier."},{"key":"registration_needed","label":"For property transactions — does the POA need Sub-Registrar registration?","type":"radio","required":true,"step":2,"score_weight":10,"options":["Yes — property sale or purchase (registration MANDATORY)","No — property management only (notarised POA sufficient)","Not sure — please advise","Not applicable (not for property)"],"eligibility_rule":{"warn_if":"Yes — property sale or purchase (registration MANDATORY)","message":"For property sales/purchases, the POA MUST be registered with the Sub-Registrar in India. Our team will coordinate this after you execute the POA abroad.","severity":"soft"}},{"key":"attestation_method","label":"Where will you sign and attest the POA?","type":"radio","required":true,"step":2,"score_weight":10,"options":["At Indian Consulate / Embassy in my country","Before a Notary Public + Apostille","Before a Notary Public only (no Apostille)","Not sure — need guidance"],"description":"Indian Consulate attestation is the most reliable option"},{"key":"agent_name","label":"Agent\'s Full Name (the person in India who will act on your behalf)","type":"text","required":true,"step":2,"score_weight":10,"placeholder":"Full legal name as in their Aadhaar / PAN"},{"key":"agent_relationship","label":"Relationship with the Agent","type":"select","required":true,"step":2,"score_weight":5,"options":["Father","Mother","Spouse","Son","Daughter","Brother","Sister","Trusted Friend","Lawyer / Advocate","CA / Chartered Accountant","Other professional agent"]},{"key":"agent_in_india","label":"Is the agent currently residing in India?","type":"radio","required":true,"step":2,"score_weight":5,"options":["Yes — living in India permanently","Yes — temporarily in India","No — also an NRI"],"eligibility_rule":{"warn_if":"No — also an NRI","message":"An NRI agent adds complexity. We can help structure this but it requires additional steps.","severity":"soft"}},{"key":"powers_to_grant","label":"Additional powers to include (check all that apply)","type":"checkbox","required":false,"step":3,"score_weight":5,"options":["Sell and execute sale deed","Purchase and execute purchase deed","Collect rent and issue receipts","Sign tenancy agreements","Apply for or manage bank accounts","File tax returns and collect refunds","Represent in court / legal proceedings","Pay property tax and utility bills","Manage insurance policies","Handle inheritance / succession matters"]},{"key":"property_value","label":"Approximate property value (if property transaction)","type":"radio","required":false,"step":3,"score_weight":5,"options":["Under ₹25 lakhs","₹25–50 lakhs","₹50 lakhs – 1 crore","₹1–2 crore","₹2–5 crore","Above ₹5 crore","Not applicable"],"description":"Property value affects stamp duty and registration fees"},{"key":"principal_country","label":"Your Country of Residence","type":"text","required":true,"step":3,"score_weight":5,"placeholder":"e.g. USA, UK, C