            'itr-filing' => '[{"key":"nri_status","label":"Your Indian tax residency status for this financial year","type":"radio","required":true,"step":1,"score_weight":20,"options":["NRI — stayed less than 182 days in India","RNOR — Resident Not Ordinarily Resident","Returned to India this year (RNOR rules apply for 2 years)","Not sure — need you to determine my status"],"description":"Your status determines what income is taxable in India — the most critical question"},{"key":"assessment_year","label":"Assessment Year (for which ITR to file)","type":"select","required":true,"step":1,"score_weight":10,"options":["2024-25 (FY 2023-24)","2023-24 (FY 2022-23)","2022-23 (FY 2021-22)","2021-22 (FY 2020-21)","Multiple years — need to file for more than 1 year"],"eligibility_rule":{"warn_if":"Multiple years — need to file for more than 1 year","message":"Filing multiple years is possible. We need documents for each year separately.","severity":"soft"}},{"key":"income_sources","label":"Which Indian income sources apply to you? (check all that apply)","type":"checkbox","required":true,"step":1,"score_weight":20,"options":["Rental Income from Indian Property","Capital Gains — Sale of Indian Property","Capital Gains — Sale of Shares / Mutual Funds","Interest from NRO Bank Account","Interest from NRE Bank Account (tax-free — but may need reporting)","Interest from Fixed Deposits in India","Dividends from Indian Companies / Mutual Funds","Pension from Indian Government / PSU","Salary received in India","Business or Professional Income from India","No Indian income — filing ONLY to claim TDS refund"],"description":"Select all that apply — even exempt income may need to be reported"},{"key":"has_pan","label":"PAN Card status","type":"radio","required":true,"step":2,"score_weight":15,"options":["Yes — active PAN and I know the PAN number","Yes — active PAN but number not with me","PAN exists but may be inactive / not linked to Aadhaar","No PAN — never applied"],"eligibility_rul