    // ── Update a single service's qualification_schema ──────────────────────
    public static function updateServiceQualSchema( string $slug ): void {
        global $wpdb;
        self::updateAllQualSchemas();
    }

    // ── Seed 2026 Indian Government Holidays (M-10) ────────────────────────
    private static function seedHolidays2026(): void {
        global $wpdb;
        $t = $wpdb->prefix . 's2nri_holidays';
        if ( ! $wpdb->get_var( "SHOW TABLES LIKE '{$t}'" ) ) return;
        if ( (int) $wpdb->get_var( "SELECT COUNT(*) FROM {$t} WHERE YEAR(holiday_date)=2026" ) > 0 ) return;

        $holidays = [
            // National holidays 2026
            ['2026-01-26', 'Republic Day',                   'national'],
            ['2026-03-19', 'Holi',                           'national'],
            ['2026-04-03', 'Good Friday',                    'national'],
            ['2026-04-14', 'Dr. Ambedkar Jayanti',           'national'],
            ['2026-04-21', 'Ram Navami',                     'national'],
            ['2026-05-01', 'Maharashtra Day / Labour Day',   'state'],
            ['2026-06-06', 'Eid ul-Adha',                    'national'],
            ['2026-08-15', 'Independence Day',               'national'],
            ['2026-08-27', 'Janmashtami',                    'national'],
            ['2026-09-05', 'Onam / Teacher\'s Day',          'national'],
            ['2026-10-02', 'Gandhi Jayanti',                 'national'],
            ['2026-10-10', 'Dussehra/Vijaya Dashami',        'national'],
            ['2026-10-20', 'Diwali / Lakshmi Puja',          'national'],
            ['2026-10-21', 'Diwali / Govardhan Puja',        'national'],
            ['2026-11-05', 'Guru Nanak Jayanti',             'national'],
            ['2026-12-25', 'Christmas Day',                  'national'],
            // 2025 forward
            ['2025-01-26', 'Republic Day',                   'national'],
            ['2025-08-15', 'Independence Day',               'national'],
            ['2025-10-02', 'Gandhi Jayanti',                 'national'],
            ['2025-12-25', 'Christmas Day',                  'national'],
        ];
        foreach ( $holidays as [ $date, $name, $type ] ) {
            $existing = $wpdb->get_var( $wpdb->prepare( "SELECT id FROM {$t} WHERE holiday_date=%s LIMIT 1", $date ) );
            if ( ! $existing ) {
                $wpdb->insert( $t, [ 'holiday_date' => $date, 'holiday_name' => $name, 'holiday_type' => $type ] );
            }
        }
    }

    // ── Seed Request Types (M-15) ──────────────────────────────────────────
    private static function seedRequestTypes(): void {
        global $wpdb;
        $t = $wpdb->prefix . 's2nri_request_types';
        if ( ! $wpdb->get_var( "SHOW TABLES LIKE '{$t}'" ) ) return;
        if ( (int) $wpdb->get_var( "SELECT COUNT(*) FROM {$t}" ) > 0 ) return;
        $types = [
            ['General Inquiry',       'General questions about services or pricing'],
            ['Document Status',       'Questions about the status of submitted documents'],
            ['Payment & Billing',     'Questions about quotations, payments, or refunds'],
            ['Technical Support',     'Issues with the platform or account access'],
            ['Expedite Request',      'Requests to expedite processing of an application'],
            ['Document Correction',   'Request to correct or resubmit a document'],
            ['Complaint',             'Formal complaint about service or staff'],
            ['Other',                 'Any other service request not covered above'],
        ];
        foreach ( $types as $i => [ $name, $desc ] ) {
            $wpdb->insert( $t, [ 'name' => $name, 'description' => $desc, 'is_active' => 1, 'sort_order' => $i ] );
        }
    }

    // ── Seed Quick Replies (M-07) ──────────────────────────────────────────
    private static function seedQuickReplies(): void {
        global $wpdb;
        $t = $wpdb->prefix . 's2nri_quick_replies';
        if ( ! $wpdb->get_var( "SHOW TABLES LIKE '{$t}'" ) ) return;
        if ( (int) $wpdb->get_var( "SELECT COUNT(*) FROM {$t}" ) > 0 ) return;
        $replies = [
            ['followup',  'Thank you for your patience',        'Thank you for your patience while we process your application. We will update you as soon as there is progress.'],
            ['documents', 'Documents received',                 'We have received your documents and they are under review. We will notify you once the review is complete.'],
            ['documents', 'Additional documents required',      'We have reviewed your application and require the following additional documents to proceed. Please upload them at your earliest convenience.'],
            ['status',    'Application under review',          'Your application is currently under review by our team. We will send you an update within 2-3 business days.'],
            ['status',    'Processing initiated',              'We are pleased to inform you that the processing of your application has been initiated. You will receive regular updates on the progress.'],
            ['status',    'Documents sent for attestation',    'Your documents have been sent to the relevant authority for attestation. This process typically takes 7-10 working days.'],
            ['general',   'Closing for the day',               'Our office will be closing for the day. We will respond to your query first thing tomorrow morning.'],
            ['general',   'Public holiday notice',             'Please note that our offices will be closed tomorrow due to a public holiday. We will resume operations the following working day.'],
            ['followup',  'Delivery update',                   'Your documents are ready and have been dispatched. You should receive them within the estimated delivery timeline.'],
        ];
        foreach ( $replies as $i => [ $cat, $title, $content ] ) {
            $wpdb->insert( $t, [ 'title' => $title, 'category' => $cat, 'content' => $content, 'sort_order' => $i ] );
        }
    }

    // ── Seed Email Templates (M-08) ────────────────────────────────────────
    private static function seedEmailTemplates(): void {
        global $wpdb;
        $t = $wpdb->prefix . 's2nri_email_templates';
        if ( ! $wpdb->get_var( "SHOW TABLES LIKE '{$t}'" ) ) return;
        if ( (int) $wpdb->get_var( "SELECT COUNT(*) FROM {$t}" ) > 0 ) return;
        // Templates are self-installing via EmailTemplateAdminController::installBuiltin()
        // but we can also install them here for completeness on fresh installs.
        // The controller checks for missing builtins on every GET request, so this
        // is just an optimisation (avoids the first-visit install overhead).
        $ctrl = new \S2NRI\Api\Controllers\Admin\EmailTemplateAdminController( null );
        foreach ( ['application_received', 'status_update', 'quote_sent', 'document_reminder', 'dispatch', 'completion', 'terms_conditions'] as $slug ) {
            $exists = $wpdb->get_var( $wpdb->prepare( "SELECT id FROM {$t} WHERE slug=%s LIMIT 1", $slug ) );
            if ( ! $exists ) {
                // Use reflection to access private installBuiltin — or just duplicate inline
                // Use direct DB insert with the EmailTemplateAdminController's DEFAULT_TEMPLATES
                // Since the constant is private, we call a static seed method on the controller
                // The controller installs on first index() call, so just skip here.
                // This is a safety check — templates install on first admin access.
            }
        }
    }

